<script setup lang="ts">import{ref}from'vue';import{graphApi}from'../api/p2';import{ElMessage}from'element-plus';import PageHeader from'../components/PageHeader.vue';const info=ref<any>(null),cycles=ref<any[]>([]);async function build(){const r:any=await graphApi.build();info.value=r.data;ElMessage.success('目录链接图构建完成')}async function detect(){const r:any=await graphApi.cycles();cycles.value=r.data?.cycles||[]}</script>
<template><PageHeader title="图与环检测" description="构建目录链接图并检查循环引用"/><div class="grid grid-2"><div class="card"><h3 class="card-title">链接关系图</h3><p class="muted">将目录节点抽象为图结构，检测异常循环路径。</p><button class="btn" @click="build">构建关系图</button><div v-if="info" class="list-row" style="margin-top:18px">节点 {{info.nodeCount??'—'}} · 连接 {{info.edgeCount??'—'}}</div></div><div class="card"><h3 class="card-title">循环路径</h3><button class="btn secondary" @click="detect">检测循环</button><div v-for="(c,i) in cycles" :key="i" class="list-row">{{Array.isArray(c)?c.join(' → '):c}}</div><div v-if="!cycles.length" class="empty">尚未发现循环，或尚未执行检测</div></div></div></template>
